package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.ActividadCiclo
import com.example.sgva.domain.AvanceCiclo
import com.example.sgva.domain.CicloNoEncontradoException
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.ConfiguracionSeguimiento
import com.example.sgva.domain.EstadoActividad
import com.example.sgva.domain.FaseCiclo
import com.example.sgva.domain.ParticipacionConSemaforo
import java.time.LocalDate

/**
 * Módulo 5 — seguimiento del avance de un ciclo (`DESIGN_SGVA.md` §0.1 y §2,
 * V6). Para un [ciclo] y una [fechaReferencia] —recibida siempre como
 * parámetro, nunca leída del reloj del sistema (`DESIGN_SGVA.md` §0.1)—
 * calcula el avance por fase, las actividades vencidas y próximas a vencer,
 * los factores con preevaluación pendiente y la participación de los
 * actores, aplicando exactamente las reglas de `DESIGN_SGVA.md` §0.1.
 */
class CalcularAvanceCicloUseCase(
    private val repositorio: AcademicDataRepository,
    private val configuracionPonderaciones: ConfiguracionPonderaciones,
    private val configuracionSeguimiento: ConfiguracionSeguimiento,
) {

    /** @throws CicloNoEncontradoException si no existe el [ciclo] referenciado. */
    fun ejecutar(ciclo: String, fechaReferencia: LocalDate): AvanceCiclo {
        repositorio.buscarCicloPorId(ciclo) ?: throw CicloNoEncontradoException(ciclo)

        val actividades = repositorio.listarActividadesPorCiclo(ciclo)
        val actividadesPorFase = actividades.groupBy { it.fase }

        val avancePorFase = FaseCiclo.RANGO_NUMERO.associateWith { numero ->
            avanceDeFase(actividadesPorFase[numero].orEmpty())
        }
        val avanceCiclo = avancePorFase.values.filterNotNull().let { presentes ->
            if (presentes.isEmpty()) null else presentes.average()
        }

        val factoresDelGrupo = repositorio.listarGruposEvaluadorPorCiclo(ciclo).flatMap { it.factores }.toSet()
        val factoresConPendiente = factoresDelGrupo.filter { factor ->
            caracteristicasConPreevaluacionPendiente(ciclo, factor)
        }.toSet()

        val participacionConSemaforo = repositorio.listarParticipacionPorCiclo(ciclo).map { participacion ->
            ParticipacionConSemaforo(
                participacion = participacion,
                semaforo = participacion.semaforo(configuracionSeguimiento),
            )
        }

        return AvanceCiclo(
            ciclo = ciclo,
            avancePorFase = avancePorFase,
            avanceCiclo = avanceCiclo,
            actividadesVencidas = actividades.filter { it.estaVencida(fechaReferencia) },
            actividadesProximasAVencer = actividades.filter {
                it.estaProximaAVencer(fechaReferencia, configuracionSeguimiento.diasProximaAVencer)
            },
            factoresConPreevaluacionPendiente = factoresConPendiente,
            participacionActores = participacionConSemaforo,
        )
    }

    /** Regla de §0.1: completadas / total; ausente si la fase no tiene actividades. */
    private fun avanceDeFase(actividadesDeFase: List<ActividadCiclo>): Double? {
        if (actividadesDeFase.isEmpty()) return null
        val completadas = actividadesDeFase.count { it.estado == EstadoActividad.COMPLETADA }
        return completadas.toDouble() / actividadesDeFase.size
    }

    /**
     * `true` si alguna característica del [factor] no tiene ninguna
     * preevaluación registrada en el [ciclo] (`DESIGN_SGVA.md` §0.1).
     */
    private fun caracteristicasConPreevaluacionPendiente(ciclo: String, factor: String): Boolean {
        val caracteristicasDelFactor = configuracionPonderaciones.caracteristicas
            .filter { it.factor == factor }
            .map { it.id }
            .toSet()
        val caracteristicasConPreevaluacion = repositorio.listarPreevaluacionesPorCiclo(ciclo)
            .map { it.caracteristica }
            .toSet()
        return (caracteristicasDelFactor - caracteristicasConPreevaluacion).isNotEmpty()
    }
}

package com.example.sgva.domain

/**
 * Participación de un actor en las encuestas de un [CicloAutoevaluacion]
 * (Módulo 5, `DESIGN_SGVA.md` §0.1 y §1, V6). No depende de frameworks,
 * bases de datos ni sistemas de archivos.
 *
 * Su clave natural es la combinación de [ciclo] y [actor]: no tiene un `id`
 * propio. [actor] es un texto abierto, no uno de los siete [TipoEstamento]:
 * la fuente institucional agrupa actores de forma distinta (ej. empleadores
 * y aliados estratégicos juntos).
 *
 * @property ciclo identificador del [CicloAutoevaluacion] al que pertenece.
 * @property actor texto abierto que identifica al actor.
 * @property poblacion tamaño de la población del actor; entero no negativo.
 * @property muestra tamaño de la muestra; entero no negativo, `muestra <= poblacion`.
 * @property respuestas respuestas recibidas; entero no negativo, `respuestas <= muestra`.
 */
data class ParticipacionActor(
    val ciclo: String,
    val actor: String,
    val poblacion: Int,
    val muestra: Int,
    val respuestas: Int,
) {
    init {
        ReglasDeFormato.exigirNoVacio(ciclo, "ciclo")
        ReglasDeFormato.exigirNoVacio(actor, "actor")
        if (poblacion < 0) throw CantidadNegativaException("poblacion", poblacion)
        if (muestra < 0) throw CantidadNegativaException("muestra", muestra)
        if (respuestas < 0) throw CantidadNegativaException("respuestas", respuestas)
        if (muestra > poblacion) {
            throw ParticipacionInconsistenteException(
                "La muestra ($muestra) no puede ser mayor que la población ($poblacion).",
            )
        }
        if (respuestas > muestra) {
            throw ParticipacionInconsistenteException(
                "Las respuestas ($respuestas) no pueden ser mayores que la muestra ($muestra).",
            )
        }
    }

    /**
     * Porcentaje diligenciado (`DESIGN_SGVA.md` §0.1): respuestas / muestra,
     * ausente si la muestra es `0`.
     */
    val porcentajeDiligenciado: Double?
        get() = if (muestra == 0) null else respuestas.toDouble() / muestra

    /**
     * Semáforo de participación derivado de [porcentajeDiligenciado] según
     * los umbrales de [configuracion] (`DESIGN_SGVA.md` §0.1). No es una
     * propiedad almacenada: los umbrales siempre provienen de una fuente de
     * configuración externa, nunca se hardcodean en el dominio.
     */
    fun semaforo(configuracion: ConfiguracionSeguimiento): TipoSemaforo? =
        configuracion.semaforoDe(porcentajeDiligenciado)
}

package com.example.sgva.domain

/**
 * Objeto de valor puro que agrupa la configuración del seguimiento del
 * proceso institucional de autoevaluación (Módulo 5, `DESIGN_SGVA.md` §0.1,
 * V6): los umbrales del semáforo de participación y el número de días para
 * considerar una actividad "próxima a vencer". No depende de frameworks,
 * bases de datos ni sistemas de archivos: ningún umbral se hardcodea en el
 * dominio ni en los casos de uso.
 *
 * @property umbralRojoNaranja porcentaje diligenciado por debajo del cual el
 *   semáforo es [TipoSemaforo.ROJO] (en el criterio vigente, `0.6`).
 * @property umbralNaranjaVerde porcentaje diligenciado a partir del cual el
 *   semáforo es [TipoSemaforo.VERDE] (en el criterio vigente, `0.8`).
 * @property diasProximaAVencer número de días a partir de la fecha de
 *   referencia dentro de los cuales una actividad no completada se considera
 *   próxima a vencer (en el criterio vigente, `7`).
 */
data class ConfiguracionSeguimiento(
    val umbralRojoNaranja: Double,
    val umbralNaranjaVerde: Double,
    val diasProximaAVencer: Int,
) {
    init {
        if (umbralRojoNaranja < 0.0 || umbralRojoNaranja >= umbralNaranjaVerde || umbralNaranjaVerde > 1.0) {
            throw UmbralesSemaforoInvalidosException(
                "Los umbrales del semáforo deben cumplir 0 <= umbralRojoNaranja < umbralNaranjaVerde <= 1; " +
                    "valores recibidos: umbralRojoNaranja=$umbralRojoNaranja, umbralNaranjaVerde=$umbralNaranjaVerde.",
            )
        }
        if (diasProximaAVencer < 0) {
            throw DiasProximaAVencerInvalidoException(diasProximaAVencer)
        }
    }

    /**
     * Deriva el semáforo de un [porcentaje] diligenciado (`DESIGN_SGVA.md`
     * §0.1): ausente si [porcentaje] es ausente.
     */
    fun semaforoDe(porcentaje: Double?): TipoSemaforo? = when {
        porcentaje == null -> null
        porcentaje < umbralRojoNaranja -> TipoSemaforo.ROJO
        porcentaje < umbralNaranjaVerde -> TipoSemaforo.NARANJA
        else -> TipoSemaforo.VERDE
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.CicloNoEncontradoException
import com.example.sgva.domain.EvaluacionDocumental

/**
 * Consolida las preevaluaciones de cada característica de un ciclo en una
 * [EvaluacionDocumental] (Módulo 5, `DESIGN_SGVA.md` §0.1 "Consolidación" y
 * §2, V6): la calificación consolidada es el promedio simple de las
 * calificaciones de sus preevaluaciones, sin redondear. Si no hay
 * preevaluaciones de una característica, no se genera evaluación documental
 * para ella (ausente, nunca `0`).
 *
 * Al guardar directamente mediante el repositorio —y no mediante
 * `RegistrarEvaluacionDocumentalUseCase`— una consolidación repetida
 * sobrescribe la evaluación documental anterior en lugar de rechazarse como
 * duplicado, para poder recalcularla cuando se agregan nuevas
 * preevaluaciones. No altera el comportamiento de
 * `CalcularResultadoAutoevaluacionUseCase`, que sigue leyendo
 * `EvaluacionDocumental` de la forma de siempre.
 */
class ConsolidarPreevaluacionesUseCase(
    private val repositorio: AcademicDataRepository,
) {

    /**
     * @throws CicloNoEncontradoException si no existe el [ciclo] referenciado.
     */
    fun ejecutar(ciclo: String): List<EvaluacionDocumental> {
        val cicloRegistrado = repositorio.buscarCicloPorId(ciclo) ?: throw CicloNoEncontradoException(ciclo)

        return repositorio.listarPreevaluacionesPorCiclo(ciclo)
            .groupBy { it.caracteristica }
            .map { (caracteristica, preevaluaciones) ->
                val consolidada = EvaluacionDocumental(
                    programa = cicloRegistrado.programa,
                    caracteristica = caracteristica,
                    periodo = cicloRegistrado.periodo,
                    calificacion = preevaluaciones.map { it.calificacion }.average(),
                )
                repositorio.guardarEvaluacionDocumental(consolidada)
            }
    }
}

package com.example.sgva.application

import com.example.sgva.domain.ActividadCiclo
import com.example.sgva.domain.Caracteristica
import com.example.sgva.domain.CicloAutoevaluacion
import com.example.sgva.domain.CicloNoEncontradoException
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.ConfiguracionSeguimiento
import com.example.sgva.domain.EstadoActividad
import com.example.sgva.domain.GrupoEvaluador
import com.example.sgva.domain.ParticipacionActor
import com.example.sgva.domain.PreevaluacionEvaluador
import com.example.sgva.domain.TipoSemaforo
import com.example.sgva.usecases.CalcularAvanceCicloUseCase
import com.example.sgva.usecases.RegistrarCicloAutoevaluacionUseCase
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import java.time.LocalDate
import kotlin.test.assertEquals
import kotlin.test.assertNull
import kotlin.test.assertTrue

class CalcularAvanceCicloUseCaseTest {

    private val repositorio = RepositorioAcademicoFalso()
    private val configuracionPonderaciones = ConfiguracionPonderaciones(
        caracteristicas = listOf(
            Caracteristica(id = "C1", nombre = "Característica 1", factor = "F1", ponderacion = 0.5),
            Caracteristica(id = "C2", nombre = "Característica 2", factor = "F1", ponderacion = 0.5),
            Caracteristica(id = "C3", nombre = "Característica 3", factor = "F2", ponderacion = 1.0),
        ),
        pesosFactores = mapOf("F1" to 0.6, "F2" to 0.4),
        pesoEncuestas = 0.4,
        pesoDocumental = 0.6,
    )
    private val configuracionSeguimiento = ConfiguracionSeguimiento(0.6, 0.8, 7)
    private val calcularAvance =
        CalcularAvanceCicloUseCase(repositorio, configuracionPonderaciones, configuracionSeguimiento)

    @BeforeEach
    fun registrarCicloBase() {
        RegistrarCicloAutoevaluacionUseCase(repositorio).ejecutar(
            CicloAutoevaluacion(id = "EGSTI-20261", programa = "EGSTI", periodo = "20261"),
        )
    }

    @Test
    fun `el avance de una fase sin actividades es ausente`() {
        val avance = calcularAvance.ejecutar("EGSTI-20261", LocalDate.of(2026, 6, 1))

        assertNull(avance.avancePorFase[1])
        assertNull(avance.avanceCiclo)
    }

    @Test
    fun `el avance de una fase es completadas sobre total`() {
        repositorio.guardarActividad(actividad(id = "1.1", fase = 1, estado = EstadoActividad.COMPLETADA))
        repositorio.guardarActividad(actividad(id = "1.2", fase = 1, estado = EstadoActividad.EN_CURSO))

        val avance = calcularAvance.ejecutar("EGSTI-20261", LocalDate.of(2026, 6, 1))

        assertEquals(0.5, avance.avancePorFase[1])
    }

    @Test
    fun `el avance del ciclo es el promedio de las fases con avance calculable`() {
        repositorio.guardarActividad(actividad(id = "1.1", fase = 1, estado = EstadoActividad.COMPLETADA))
        repositorio.guardarActividad(actividad(id = "2.1", fase = 2, estado = EstadoActividad.PLANIFICADA))

        val avance = calcularAvance.ejecutar("EGSTI-20261", LocalDate.of(2026, 6, 1))

        assertEquals(0.5, avance.avanceCiclo)
    }

    @Test
    fun `una actividad vencida no completada aparece en actividadesVencidas`() {
        repositorio.guardarActividad(
            actividad(id = "1.1", fase = 1, fin = LocalDate.of(2026, 1, 1), estado = EstadoActividad.EN_CURSO),
        )

        val avance = calcularAvance.ejecutar("EGSTI-20261", LocalDate.of(2026, 6, 1))

        assertEquals(listOf("1.1"), avance.actividadesVencidas.map { it.id })
        assertTrue(avance.actividadesProximasAVencer.isEmpty())
    }

    @Test
    fun `una actividad que vence dentro de los dias configurados aparece en proximasAVencer`() {
        repositorio.guardarActividad(
            actividad(id = "1.1", fase = 1, fin = LocalDate.of(2026, 6, 5), estado = EstadoActividad.PLANIFICADA),
        )

        val avance = calcularAvance.ejecutar("EGSTI-20261", LocalDate.of(2026, 6, 1))

        assertEquals(listOf("1.1"), avance.actividadesProximasAVencer.map { it.id })
        assertTrue(avance.actividadesVencidas.isEmpty())
    }

    @Test
    fun `un factor con alguna caracteristica sin preevaluacion queda pendiente`() {
        repositorio.guardarGrupoEvaluador(GrupoEvaluador(ciclo = "EGSTI-20261", factores = setOf("F1"), taller = 1))
        repositorio.guardarPreevaluacion(
            PreevaluacionEvaluador(ciclo = "EGSTI-20261", caracteristica = "C1", evaluador = "EVAL-01", calificacion = 4.0),
        )

        val avance = calcularAvance.ejecutar("EGSTI-20261", LocalDate.of(2026, 6, 1))

        assertEquals(setOf("F1"), avance.factoresConPreevaluacionPendiente)
    }

    @Test
    fun `un factor con todas sus caracteristicas preevaluadas no queda pendiente`() {
        repositorio.guardarGrupoEvaluador(GrupoEvaluador(ciclo = "EGSTI-20261", factores = setOf("F1"), taller = 1))
        repositorio.guardarPreevaluacion(
            PreevaluacionEvaluador(ciclo = "EGSTI-20261", caracteristica = "C1", evaluador = "EVAL-01", calificacion = 4.0),
        )
        repositorio.guardarPreevaluacion(
            PreevaluacionEvaluador(ciclo = "EGSTI-20261", caracteristica = "C2", evaluador = "EVAL-01", calificacion = 4.0),
        )

        val avance = calcularAvance.ejecutar("EGSTI-20261", LocalDate.of(2026, 6, 1))

        assertTrue(avance.factoresConPreevaluacionPendiente.isEmpty())
    }

    @Test
    fun `la participacion de actores se devuelve con su semaforo ya resuelto`() {
        repositorio.guardarParticipacion(
            ParticipacionActor(ciclo = "EGSTI-20261", actor = "Estudiantes", poblacion = 100, muestra = 100, respuestas = 90),
        )

        val avance = calcularAvance.ejecutar("EGSTI-20261", LocalDate.of(2026, 6, 1))

        assertEquals(1, avance.participacionActores.size)
        assertEquals(TipoSemaforo.VERDE, avance.participacionActores.first().semaforo)
    }

    @Test
    fun `calcular el avance de un ciclo inexistente es rechazado`() {
        assertThrows<CicloNoEncontradoException> {
            calcularAvance.ejecutar("NO-EXISTE", LocalDate.of(2026, 6, 1))
        }
    }

    private fun actividad(
        id: String,
        fase: Int,
        inicio: LocalDate = LocalDate.of(2026, 1, 1),
        fin: LocalDate = LocalDate.of(2026, 12, 1),
        estado: EstadoActividad,
    ): ActividadCiclo = ActividadCiclo(
        id = id,
        ciclo = "EGSTI-20261",
        fase = fase,
        descripcion = "Actividad de prueba",
        responsable = "Comité de aseguramiento de la calidad",
        fechaInicioPlanificada = inicio,
        fechaFinPlanificada = fin,
        estado = estado,
    )
}

package com.example.sgva.application

import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.ResultadoAutoevaluacion
import com.example.sgva.infrastructure.configuracion.CargadorConfiguracionPonderaciones
import com.example.sgva.infrastructure.parsing.CsvDocumentParser
import com.example.sgva.usecases.CalcularResultadoAutoevaluacionUseCase
import de.siegmar.fastcsv.reader.CsvReader
import org.junit.jupiter.api.Test
import kotlin.test.assertTrue

/**
 * Valida `CalcularResultadoAutoevaluacionUseCase` contra el modelo de
 * autoevaluación 2025 diligenciado (`DESIGN_SGVA.md` §0.1), usando los
 * fixtures reales de ponderaciones, resultados de encuesta por pregunta y
 * evaluación documental de `src/test/resources/fixtures/modelo2025`.
 *
 * `esperados_autoevaluacion.csv` contiene únicamente códigos y valores
 * numéricos tomados del modelo diligenciado 2025 (no se deriva de este
 * cálculo): es el oráculo contra el que se compara, con una tolerancia de
 * `1e-4` para absorber el redondeo propio de una hoja de cálculo.
 */
class CalcularResultadoAutoevaluacionModelo2025Test {

    private val programa = "EGSTI"
    private val periodo = "20252"
    private val tolerancia = 1e-4

    private val resultado: ResultadoAutoevaluacion = calcularResultado()
    private val esperadosPorCaracteristica = esperadosDelNivel("caracteristica")
    private val esperadosPorFactor = esperadosDelNivel("factor")
    private val esperadoGlobal = esperadosDelNivel("global").getValue("EGSTI")

    @Test
    fun `el promedio por caracteristica reproduce el modelo 2025 diligenciado`() {
        val diferencias = esperadosPorCaracteristica.mapNotNull { (id, esperado) ->
            diferenciaFueraDeTolerancia(id, esperado, resultado.promediosPorCaracteristica[id])
        }

        assertTrue(diferencias.isEmpty(), diferencias.joinToString("\n", prefix = "\n"))
    }

    @Test
    fun `el promedio por factor reproduce el modelo 2025 diligenciado`() {
        val diferencias = esperadosPorFactor.mapNotNull { (id, esperado) ->
            diferenciaFueraDeTolerancia(id, esperado, resultado.promediosPorFactor[id])
        }

        assertTrue(diferencias.isEmpty(), diferencias.joinToString("\n", prefix = "\n"))
    }

    @Test
    fun `el promedio global reproduce el modelo 2025 diligenciado`() {
        val diferencia = diferenciaFueraDeTolerancia("EGSTI", esperadoGlobal, resultado.promedioGlobal)

        assertTrue(diferencia == null, diferencia ?: "")
    }

    private fun diferenciaFueraDeTolerancia(id: String, esperado: Double, calculado: Double?): String? {
        if (calculado == null) return "$id: esperado $esperado, calculado ausente (null)"
        val diferencia = calculado - esperado
        if (Math.abs(diferencia) <= tolerancia) return null
        return "$id: esperado $esperado, calculado $calculado (diferencia ${"%+.6f".format(diferencia)})"
    }

    private fun calcularResultado(): ResultadoAutoevaluacion {
        val repositorio = RepositorioAcademicoFalso()
        val parser = CsvDocumentParser()

        parser.extraerResultadosEncuestaPregunta(
            "resultados_encuesta_pregunta.csv",
            fixture("resultados_encuesta_pregunta.csv"),
        ).forEach { repositorio.guardarResultadoEncuestaPregunta(it) }

        parser.extraerEvaluacionesDocumentales(
            "evaluacion_documental.csv",
            fixture("evaluacion_documental.csv"),
        ).forEach { repositorio.guardarEvaluacionDocumental(it) }

        val configuracion: ConfiguracionPonderaciones = CargadorConfiguracionPonderaciones().parsear(
            contenido = String(fixture("ponderaciones_modelo_2025.csv")),
            origen = "ponderaciones_modelo_2025.csv",
        )

        return CalcularResultadoAutoevaluacionUseCase(repositorio, configuracion).ejecutar(programa, periodo)
    }

    /** Lee `esperados_autoevaluacion.csv` (columnas `nivel,id,valor`) y filtra por [nivel]. */
    private fun esperadosDelNivel(nivel: String): Map<String, Double> {
        val contenido = String(fixture("esperados_autoevaluacion.csv"))
        val filas = CsvReader.builder().ofCsvRecord(contenido).use { lector -> lector.map { it.fields } }
        return filas.drop(1)
            .filter { (filaNivel, _, _) -> filaNivel == nivel }
            .associate { (_, id, valor) -> id to valor.toDouble() }
    }

    private fun fixture(nombre: String): ByteArray =
        checkNotNull(javaClass.getResourceAsStream("/fixtures/modelo2025/$nombre")) { "falta el fixture $nombre" }
            .use { it.readBytes() }
}

